mapper.select:
SELECT 
  FROM act14_link
 WHERE act14_company_id = #{companyId}
   AND act14_account_cd = #{accountCode}
 ORDER BY act14_seq, act14_provide_content_cd

mapper.insert:
INSERT INTO act14_link (act14_link_id, act14_company_id, act14_account_cd, act14_provide_content_cd, act14_seq)
SELECT #{linkId}
     , #{companyId}
     , #{accountCode}
     , #{provideContentCode}
     , ( SELECT MAX(act14_seq) + 1
           FROM act14_link
          WHERE act14_company_id = #{companyId}
            AND act14_account_cd = #{accountCode} )

WITH upsert AS ( UPDATE act14_link
                    SET act14_provide_content_cd = #{provideContentCode}
                  WHERE act14_company_id         = #{companyId}
                    AND act14_account_cd         = #{accountCode}
                    AND act14_provide_content_cd = #{provideContentCode}
                 RETURNING *
) INSERT INTO act14_link (act14_link_id, act14_company_id, act14_account_cd, act14_provide_content_cd)
  SELECT f_create_seq()
       , #{companyId}
       , #{accountCode}
       , #{provideContentCode}
   WHERE NOT EXISTS ( SELECT * FROM upsert )

mapper.update:
UPDATE act14_link
   SET act14_seq = #{seq}
 WHERE act14_link_id    = #{linkId}
   AND act14_company_id = #{companyId}

mapper.delete:
DELETE FROM act14_link
 WHERE act14_company_id = #{companyId}
   AND act14_link_id IN
#{id}
